import React, { useState, useEffect } from 'react';
import Home from './pages/Home';
import Game from './pages/Game';
import About from './pages/About';
import Settings from './pages/Settings';
import Layout from './components/Layout';
import './styles/globals.css';

function App() {
  // Estado para controlar qual página está visível
  const [view, setView] = useState('home'); 
  
  // Estado para o modo de jogo selecionado (deep, unfiltered, lab)
  const [gameMode, setGameMode] = useState(null);

  // Estado para as configurações com inicialização via localStorage
  const [settings, setSettings] = useState(() => {
    const saved = localStorage.getItem('raw_settings');
    return saved ? JSON.parse(saved) : {
      animations: true,
      explicit: true,
      language: 'PT-PT'
    };
  });

  // Efeito para guardar as definições sempre que estas forem alteradas
  useEffect(() => {
    localStorage.setItem('raw_settings', JSON.stringify(settings));
  }, [settings]);

  // Handlers de Navegação
  const handleStartGame = (modeId) => {
    setGameMode(modeId);
    setView('game');
  };

  const handleUpdateSetting = (key, value) => {
    setSettings(prev => ({ ...prev, [key]: value }));
  };

  const handleBackToHome = () => {
    setView('home');
    setGameMode(null);
  };

  return (
    <Layout 
      onOpenSettings={() => setView('settings')} 
      onOpenAbout={() => setView('about')}
      currentLang={settings.language}
    >
      {/* Página Inicial */}
      {view === 'home' && (
        <div className={settings.animations ? "animate-in fade-in duration-500" : ""}>
          <Home onNavigate={handleStartGame} />
        </div>
      )}
      
      {/* Ecrã de Jogo */}
      {view === 'game' && (
        <div className={settings.animations ? "animate-in slide-in-from-right duration-500" : ""}>
          <Game 
            modeId={gameMode} 
            onBack={handleBackToHome} 
            settings={settings} 
          />
        </div>
      )}

      {/* Página Sobre/Story */}
      {view === 'about' && (
        <div className={settings.animations ? "animate-in slide-in-from-bottom duration-500" : ""}>
          <About onBack={handleBackToHome} />
        </div>
      )}

      {/* Página de Definições */}
      {view === 'settings' && (
        <div className={settings.animations ? "animate-in slide-in-from-top duration-500" : ""}>
          <Settings 
            settings={settings} 
            onUpdate={handleUpdateSetting} 
            onBack={handleBackToHome} 
          />
        </div>
      )}
    </Layout>
  );
}

export default App;
